import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api';

export default function App() {
  const [view, setView] = useState('guest'); // 'guest' | 'admin'
  const [rooms, setRooms] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [selectedRoom, setSelectedRoom] = useState(null);
  const [filterType, setFilterType] = useState('All');

  // Form states
  const [guestName, setGuestName] = useState('');
  const [guestEmail, setGuestEmail] = useState('');
  const [guestPhone, setGuestPhone] = useState('');
  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');

  // Fetch Rooms
  const fetchRooms = async () => {
    try {
      const res = await fetch(`${API_BASE}/rooms`);
      const data = await res.json();
      setRooms(data);
    } catch (err) {
      console.error(err);
    }
  };

  // Fetch Bookings
  const fetchBookings = async () => {
    try {
      const res = await fetch(`${API_BASE}/bookings`);
      const data = await res.json();
      setBookings(data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchRooms();
    fetchBookings();
  }, []);

  // Handle Room Reservation Submit
  const handleBookingSubmit = async (e) => {
    e.preventDefault();
    const cin = new Date(checkIn);
    const cout = new Date(checkOut);
    const diffDays = Math.ceil((cout - cin) / (1000 * 60 * 60 * 24));

    if (diffDays <= 0) {
      alert('Checkout date must be after Checkin date');
      return;
    }

    const payload = {
      roomId: selectedRoom._id,
      guestName,
      guestEmail,
      guestPhone,
      checkIn,
      checkOut,
      totalNights: diffDays,
      totalAmount: diffDays * selectedRoom.pricePerNight
    };

    try {
      const res = await fetch(`${API_BASE}/bookings`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (!res.ok) {
        alert(data.error || 'Failed to book');
      } else {
        alert('Booking Confirmed successfully!');
        setSelectedRoom(null);
        fetchBookings();
        fetchRooms();
      }
    } catch (err) {
      alert('Booking request failed');
    }
  };

  const updateBookingStatus = async (id, status) => {
    await fetch(`${API_BASE}/bookings/${id}/status`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ bookingStatus: status })
    });
    fetchBookings();
    fetchRooms();
  };

  const updateRoomStatus = async (roomId, status) => {
    await fetch(`${API_BASE}/rooms/${roomId}/status`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status })
    });
    fetchRooms();
  };

  const filteredRooms = filterType === 'All' ? rooms : rooms.filter(r => r.type === filterType);

  return (
    <div>
      <nav className="navbar">
        <div className="logo">🏨 HotelPro</div>
        <div>
          <button className={`nav-btn ${view === 'guest' ? 'active' : ''}`} onClick={() => setView('guest')}>
            Guest Booking View
          </button>
          <button className={`nav-btn ${view === 'admin' ? 'active' : ''}`} onClick={() => setView('admin')}>
            Front Desk & Admin PMS
          </button>
        </div>
      </nav>

      <div className="container">
        {view === 'guest' ? (
          <div>
            <div className="filter-bar">
              <label><strong>Filter by Room Tier:</strong></label>
              <select value={filterType} onChange={(e) => setFilterType(e.target.value)}>
                <option value="All">All Rooms</option>
                <option value="Suite">Suites</option>
                <option value="Executive">Executive</option>
                <option value="Deluxe">Deluxe</option>
                <option value="Standard">Standard</option>
              </select>
            </div>

            <div className="grid">
              {filteredRooms.map((room) => (
                <div key={room._id} className="card">
                  <img src={room.image} alt={room.title} />
                  <div className="card-body">
                    <span className="badge badge-suite">{room.type}</span>
                    <h3 style={{ marginTop: '0.5rem' }}>{room.title}</h3>
                    <p style={{ color: '#64748b', fontSize: '0.9rem', margin: '0.4rem 0' }}>
                      Room #{room.roomNumber} • Capacity: {room.capacity} Guests
                    </p>
                    <p style={{ fontSize: '1.25rem', fontWeight: 'bold' }}>
                      ${room.pricePerNight} <span style={{ fontSize: '0.8rem', color: '#64748b' }}>/ night</span>
                    </p>
                    <button
                      className="book-btn"
                      disabled={room.status !== 'Available'}
                      onClick={() => setSelectedRoom(room)}
                    >
                      {room.status === 'Available' ? 'Reserve Now' : room.status}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div>
            <h2 style={{ marginBottom: '1.5rem' }}>Front Desk Booking Management</h2>
            <table>
              <thead>
                <tr>
                  <th>Guest</th>
                  <th>Room</th>
                  <th>Dates</th>
                  <th>Total</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {bookings.map((b) => (
                  <tr key={b._id}>
                    <td>
                      <strong>{b.guestName}</strong>
                      <div style={{ fontSize: '0.8rem', color: '#64748b' }}>{b.guestEmail}</div>
                    </td>
                    <td>{b.roomId?.title || 'Room Removed'} (#{b.roomId?.roomNumber})</td>
                    <td>{new Date(b.checkIn).toLocaleDateString()} → {new Date(b.checkOut).toLocaleDateString()}</td>
                    <td><strong>${b.totalAmount}</strong> ({b.totalNights} nts)</td>
                    <td>
                      <span className="badge badge-deluxe">{b.bookingStatus}</span>
                    </td>
                    <td>
                      {b.bookingStatus === 'Confirmed' && (
                        <button className="action-btn action-checkin" onClick={() => updateBookingStatus(b._id, 'Checked-In')}>
                          Check In
                        </button>
                      )}
                      {b.bookingStatus === 'Checked-In' && (
                        <button className="action-btn action-checkout" onClick={() => updateBookingStatus(b._id, 'Checked-Out')}>
                          Check Out
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            <h2 style={{ marginTop: '2.5rem', marginBottom: '1rem' }}>Room Status & Housekeeping</h2>
            <table>
              <thead>
                <tr>
                  <th>Room #</th>
                  <th>Category</th>
                  <th>Price</th>
                  <th>Status</th>
                  <th>Toggle Housekeeping</th>
                </tr>
              </thead>
              <tbody>
                {rooms.map((r) => (
                  <tr key={r._id}>
                    <td><strong>#{r.roomNumber}</strong></td>
                    <td>{r.title}</td>
                    <td>${r.pricePerNight}</td>
                    <td><span className="badge badge-suite">{r.status}</span></td>
                    <td>
                      {r.status === 'Cleaning' && (
                        <button className="action-btn action-checkin" onClick={() => updateRoomStatus(r._id, 'Available')}>
                          Mark Clean & Ready
                        </button>
                      )}
                      {r.status === 'Available' && (
                        <button className="action-btn action-checkout" onClick={() => updateRoomStatus(r._id, 'Cleaning')}>
                          Send to Cleaning
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {selectedRoom && (
        <div className="modal-overlay">
          <div className="modal">
            <h3>Book {selectedRoom.title}</h3>
            <p style={{ marginBottom: '1rem', color: '#64748b' }}>${selectedRoom.pricePerNight} / night</p>
            <form onSubmit={handleBookingSubmit}>
              <input type="text" placeholder="Full Name" value={guestName} onChange={e => setGuestName(e.target.value)} required />
              <input type="email" placeholder="Email Address" value={guestEmail} onChange={e => setGuestEmail(e.target.value)} required />
              <input type="tel" placeholder="Phone Number" value={guestPhone} onChange={e => setGuestPhone(e.target.value)} required />
              <label style={{ fontSize: '0.8rem', color: '#64748b' }}>Check-In Date</label>
              <input type="date" value={checkIn} onChange={e => setCheckIn(e.target.value)} required />
              <label style={{ fontSize: '0.8rem', color: '#64748b' }}>Check-Out Date</label>
              <input type="date" value={checkOut} onChange={e => setCheckOut(e.target.value)} required />

              <div className="modal-actions">
                <button type="button" className="nav-btn" onClick={() => setSelectedRoom(null)}>Cancel</button>
                <button type="submit" className="book-btn" style={{ width: 'auto' }}>Confirm Reservation</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
